/**
 * NASA Blue Marble / Visible Earth equirectangular texture (public domain),
 * 2048x1024, embedded as a base64 data URL so the globe never depends on an
 * external URL at runtime. Source:
 * https://unpkg.com/three-globe/example/img/earth-blue-marble.jpg
 * (NASA Visible Earth, public domain). Downscaled from the 4096x2048
 * original with Lanczos resampling; JPEG quality 88.
 *
 * Note: this is ONE string literal, not a '+' chain — a chain of thousands
 * of concatenations overflows the TypeScript checker's stack.
 */
export const EARTH_TEXTURE_DATA_URL: string = 'data:image/jpeg;base64,';
